    { srcSet: "/assets/cloned/images/b8e8faa09b47.webp 500w, /assets/cloned/images/7d565dfa1b35.webp 320w", imgSrc: "/assets/cloned/images/c43c114507ba.png", title: "Data Management", description: "Daten verstehen, strukturieren und für Entscheidungen nutzbar machen. Von Data Literacy bis KI – hier bauen Sie echte Datenkompetenz für moderne Unternehmen auf.", srcSet2: "/assets/cloned/images/b8e8faa09b47.webp 500w, /assets/cloned/images/7d565dfa1b35.webp 320w", imgSrc2: "/assets/cloned/images/c43c114507ba.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/data-management", label: "Mehr zu Data Managment" },
    { srcSet: "/assets/cloned/images/4ded6d8bfc8e.webp 500w, /assets/cloned/images/886aa220ea6f.webp 320w", imgSrc: "/assets/cloned/images/4ca922b536a0.png", title: "Microsoft Office-Seminare", description: "Als autorisierter Microsoft Learning Partner bieten wir eine breite Palette an Schulungen zum offiziellen Microsoft Office Angebot an. Eigenentwickelte Seminare zu Microsoft runden das Angebot ab.", srcSet2: "/assets/cloned/images/4ded6d8bfc8e.webp 500w, /assets/cloned/images/886aa220ea6f.webp 320w", imgSrc2: "/assets/cloned/images/4ca922b536a0.png", kind: "button", href: "https://www.cegos-integrata.de/microsoft-trainings-schulungen-fuer-anwender-und-admins/microsoft-office-seminare", label: "Mehr zu Microsoft Office Trainings" },
    { srcSet: "/assets/cloned/images/2f7175a7a6d8.webp 500w, /assets/cloned/images/65761c605009.webp 320w", imgSrc: "/assets/cloned/images/581c0302c930.png", title: "Software-Einführungen & Roll-outs", description: "Steht im Rahmen der Einführung und des Roll-outs neuer Software die nahtlose Einbindung aller Geschäftsprozesse im Fokus? Wir begleiten Sie bei Ihren Vorhaben – mit dem klaren Ziel, Effizienz, Transparenz und Prozesssicherheit zu stärken.", srcSet2: "/assets/cloned/images/2f7175a7a6d8.webp 500w, /assets/cloned/images/65761c605009.webp 320w", imgSrc2: "/assets/cloned/images/581c0302c930.png", kind: "link", href: "https://www.cegos-integrata.de/kundenprojekte/qualifizierungsprojekte-it/softwareeinfuehrung-und-roll-out", label: "Mehr zu Software-Einführungen & Roll-outs" },
    { srcSet: "/assets/cloned/images/4f765c5f4b58.webp 500w, /assets/cloned/images/211fa9eba348.webp 320w", imgSrc: "/assets/cloned/images/43bd86ce4675.png", title: "Upskilling: IT-Fähigkeiten, die Mehrwert bieten", description: "Stärken Sie Ihr Team mit IT-Upskilling. Mit unseren Qualifizierungsprogrammen für unternehmensweites IT-Upskilling bereiten Sie Ihre Teams auf neue Anforderungen in ihrer Rolle vor.", srcSet2: "/assets/cloned/images/4f765c5f4b58.webp 500w, /assets/cloned/images/211fa9eba348.webp 320w", imgSrc2: "/assets/cloned/images/43bd86ce4675.png", kind: "button", href: "https://www.cegos-integrata.de/kundenprojekte/qualifizierungsprojekte-it/it-upskilling-mit-mehrwert", label: "Mehr zu IT-Upskilling" },
    { srcSet: "/assets/cloned/images/f9ae473dfaf8.webp 500w, /assets/cloned/images/0a47a4db2f1a.webp 320w", imgSrc: "/assets/cloned/images/b7df9bc640aa.png", title: "IT-Reskilling: In Zukunftsfähigkeit investieren", description: "Die digitale Transformation und neue Technologien verlangen neue Kompetenzen und Fertigkeiten. Umschulungen sind eine strategische Lösung, um flexibel auf zukünftige Herausforderungen und Veränderungen zu reagieren.", srcSet2: "/assets/cloned/images/f9ae473dfaf8.webp 500w, /assets/cloned/images/0a47a4db2f1a.webp 320w", imgSrc2: "/assets/cloned/images/b7df9bc640aa.png", kind: "button", href: "https://www.cegos-integrata.de/kundenprojekte/qualifizierungsprojekte-it/it-reskilling-umschulung", label: "Mehr zu IT-Reskilling" },
    { srcSet: "/assets/cloned/images/b62b8f933188.webp 500w, /assets/cloned/images/eb7e778629c8.webp 320w", imgSrc: "/assets/cloned/images/8154b07e4a79.png", title: "IT-Kompetenzen der Zukunft nach europäischer Norm", description: "Berufliche IKT-Rollenprofile nach europäischer Norm und e-CF: Bilden Sie Ihre Mitarbeiter:innen in diesen IKT-Job-Rollen aus: Developer - Scrum Master - Enterprise Architect - System Architect - Service Manager.", srcSet2: "/assets/cloned/images/b62b8f933188.webp 500w, /assets/cloned/images/eb7e778629c8.webp 320w", imgSrc2: "/assets/cloned/images/8154b07e4a79.png", kind: "link", href: "https://www.cegos-integrata.de/kundenprojekte/qualifizierungsprojekte-it/it-upskilling-mit-mehrwert/die-it-kompetenzen-der-zukunft-nach-europaeischer-norm", label: "Mehr zu IKT-Rollenprofilen nach europäischer Norm " },
    { srcSet: "/assets/cloned/images/d3c7bd21d3b0.webp 500w, /assets/cloned/images/afcf075fa834.webp 320w", imgSrc: "/assets/cloned/images/198d388f21a7.png", title: "Agile Methoden, Scrum & SAFe - Von den Grundlagen zur Zertifizierung", description: "Entdecken Sie unser vielfältiges Schulungsangebot rund um Agilität, Scrum und SAFe – sowohl für Fach- und Führungskräfte, Projektleiter:innen, als auch IT Mitarbeiter:innen. ", srcSet2: "/assets/cloned/images/d3c7bd21d3b0.webp 500w, /assets/cloned/images/afcf075fa834.webp 320w", imgSrc2: "/assets/cloned/images/198d388f21a7.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/scrum-und-agilitaet", label: "Mehr zu Agilität, Scrum und SAFe" },
    { srcSet: "/assets/cloned/images/5f36cf12fa8e.webp 500w, /assets/cloned/images/ab6b419e2d50.webp 320w", imgSrc: "/assets/cloned/images/4bc647603311.png", title: "SAP-Schulungen für Unternehmen", description: "Unser Trainingsprogramm umfasst sowohl klassische SAP Systeme wie R/3 und die dazugehörigen Module CRM, SRM, EWM, HCM und Business Warehouse beziehungsweise Business Objects als auch moderne Lösungen bis hin zu den aktuellen S/4HANA Anwendungen, sodass wir die gesamte Bandbreite von älteren bis zu neuesten SAP Technologien abdecken.", srcSet2: "/assets/cloned/images/5f36cf12fa8e.webp 500w, /assets/cloned/images/ab6b419e2d50.webp 320w", imgSrc2: "/assets/cloned/images/4bc647603311.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/sap-schulungen-fuer-unternehmen", label: "Mehr zu SAP Trainings" },
    { srcSet: "/assets/cloned/images/1127789f1145.webp 500w, /assets/cloned/images/686a6a7dc58a.webp 320w", imgSrc: "/assets/cloned/images/fc0eb1f88114.png", title: "Software Engineering Schulungen und Zertifizierungen", description: "Von Anforderungsmanagement über Software Design und - Architektur bis hin zu Softwaretest und Usability finden Sie hier die Vorbereitungsschulungen für die international anerkannten Standards zu IREB CPRE, ISAQB CPSA, ISTQB CT und UXQB CPUX.", srcSet2: "/assets/cloned/images/1127789f1145.webp 500w, /assets/cloned/images/686a6a7dc58a.webp 320w", imgSrc2: "/assets/cloned/images/fc0eb1f88114.png", kind: "link", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/software-engineering-schulungen-und-zertifizierungen", label: "Mehr zu Software Engineering Schulungen und Zertifizierungen" },
    { srcSet: "/assets/cloned/images/7e922765e82b.webp 500w, /assets/cloned/images/91766d7236e3.webp 320w", imgSrc: "/assets/cloned/images/83c89dc6a1e8.png", title: "Java Schulungen", description: "Entdecken Sie unser vielfältiges Schulungsangebot zu Java, der weltweit am weitesten verbreiteten Programmiersprache . Java von Grund auf lernen oder in moderne Frameworks einsteigen: praxisorientierte Trainings für sauberen Code, robuste Anwendungen und professionelle Java-Entwicklung.", srcSet2: "/assets/cloned/images/7e922765e82b.webp 500w, /assets/cloned/images/91766d7236e3.webp 320w", imgSrc2: "/assets/cloned/images/83c89dc6a1e8.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/java-schulungen", label: "Mehr zu Java Schulungen" },
    { srcSet: "/assets/cloned/images/21fe4a5adb23.webp 500w, /assets/cloned/images/93a983a83745.webp 320w", imgSrc: "/assets/cloned/images/195a14709165.png", title: "Enterprise Architecture Management und TOGAF® EA Zertifizierung", description: "EAM (Enterprise Architecture Management) strukturiert die gesamte Unternehmensarchitektur. Mit dem richtigen Know-how und dem EA Framework TOGAF ® können Sie die wesentlichen Bestandteile und Zusammenhänge. ihrer Unternehmensarchitektur gestalten und weiterentwickeln.", srcSet2: "/assets/cloned/images/21fe4a5adb23.webp 500w, /assets/cloned/images/93a983a83745.webp 320w", imgSrc2: "/assets/cloned/images/195a14709165.png", kind: "link", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/enterprise-architecture-management-und-togaf-ea-zertifizierung", label: "Mehr zu Enterprise Architecture Management und TOGAF® EA Zertifizierung" },
    { srcSet: "/assets/cloned/images/a46af0d29fce.webp 500w, /assets/cloned/images/2eee54300e00.webp 320w", imgSrc: "/assets/cloned/images/f4f9a8f961fd.png", title: "JavaScript lernen für Einsteiger:innen ", description: "Stärken Sie Ihre Teams mit Kenntnissen in JavaScript. Unsere Qualifizierungsmaßnahmen stimmen wir auch gerne auf den individuellen Kenntnisstand und Bedarf Ihrer Mitarbeiter:innen ab. Interaktive Websites, starke Tools, moderne Frameworks: Lernen Sie JavaScript praxisnah und entwickeln Sie Anwendungen, die wirklich überzeugen.", srcSet2: "/assets/cloned/images/a46af0d29fce.webp 500w, /assets/cloned/images/2eee54300e00.webp 320w", imgSrc2: "/assets/cloned/images/f4f9a8f961fd.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/javascript-programmieren-lernen", label: "Mehr zu JavaScript lernen" },
    { srcSet: "/assets/cloned/images/536906fca861.webp 500w, /assets/cloned/images/bb9c3b4835eb.webp 320w", imgSrc: "/assets/cloned/images/5e1764b88090.png", title: "Python-Schulungen", description: "Unsere Python-Schulungen vermitteln Ihnen sowohl die Grundlagen von Python als auch fortgeschrittene Konzepte wie objektorientierte Programmierung und den Umgang mit virtuellen Umgebungen. Einsteigen, vertiefen, durchstarten: Python für Analyse, KI, Webentwicklung und Automatisierung – verständlich erklärt und sofort nutzbar.", srcSet2: "/assets/cloned/images/536906fca861.webp 500w, /assets/cloned/images/bb9c3b4835eb.webp 320w", imgSrc2: "/assets/cloned/images/5e1764b88090.png", kind: "button", href: "https://www.cegos-integrata.de/leistungsangebot-informationstechnologie/python-schulungen-online-oder-praesenz", label: "Mehr zu Python-Schulungen" }
